import os
import re
import json
import time
import hmac
import hashlib
import unicodedata
from pathlib import Path
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

SESSION_DIR = os.environ.get('SESSION_DIR', '/tmp/sessions')
SECRET_KEY = os.environ.get('SECRET_KEY', os.urandom(32).hex())
MAX_SESSION_AGE = 3600

# PBKDF2 parameters for password verification
PBKDF2_ITERATIONS = 200000
PBKDF2_ALGO = 'sha256'

os.makedirs(SESSION_DIR, exist_ok=True)

def generate_session_id(username):
    """Generate a deterministic session ID from username and timestamp."""
    timestamp = str(int(time.time()))
    raw = f"{username}:{timestamp}:{SECRET_KEY}"
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()

def compute_integrity_tag(data):
    """Compute HMAC integrity tag for session data."""
    serialized = json.dumps(data, sort_keys=True, separators=(',', ':'))
    return hmac.new(SECRET_KEY.encode('utf-8'), serialized.encode('utf-8'), hashlib.sha256).hexdigest()

def verify_password(password, stored):
    """Verify a password against a stored PBKDF2 credential.

    Stored format: 'pbkdf2_sha256$<iterations>$<salt_hex>$<hash_hex>'
    Uses a salted, iterated KDF to resist brute-force / rainbow-table attacks.
    """
    try:
        scheme, iterations_s, salt_hex, hash_hex = stored.split('$')
    except (ValueError, AttributeError):
        return False
    if scheme != 'pbkdf2_sha256':
        return False
    try:
        iterations = int(iterations_s)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(hash_hex)
    except ValueError:
        return False
    derived = hashlib.pbkdf2_hmac(
        PBKDF2_ALGO, password.encode('utf-8'), salt, iterations
    )
    return hmac.compare_digest(derived, expected)

def sanitize_session_filename(session_id):
    """Sanitize session ID to prevent directory traversal.

    Security: We normalize unicode first to prevent normalization-based
    bypasses, then validate the format strictly.
    """
    # Step 1: Normalize unicode BEFORE validation
    # This prevents bypasses where pre-normalization form passes
    # the regex but post-normalization form contains dangerous chars
    normalized = unicodedata.normalize('NFC', session_id)

    # Step 2: Check that normalized ID matches expected hex format
    if not re.match(r'^[a-f0-9]{64}$', normalized):
        return None

    return normalized

def resolve_session_path(session_id):
    """Resolve the full path for a session file with traversal protection."""
    safe_id = sanitize_session_filename(session_id)
    if safe_id is None:
        return None

    # Construct path and verify it's within SESSION_DIR
    session_path = os.path.join(SESSION_DIR, safe_id + '.json')

    # Canonicalize to resolve any symlinks or relative components
    canonical = os.path.realpath(session_path)
    base_dir = os.path.realpath(SESSION_DIR)

    if not canonical.startswith(base_dir + os.sep):
        return None

    return canonical  # Return canonical path, not user-influenced

def load_session(session_id):
    """Load and validate a session from disk."""
    path = resolve_session_path(session_id)
    if path is None:
        return None

    if not os.path.exists(path):
        return None

    with open(path, 'r') as f:
        data = json.load(f)

    # Verify session hasn't expired
    if time.time() - data.get('created_at', 0) > MAX_SESSION_AGE:
        os.unlink(path)
        return None

    # Verify integrity
    stored_tag = data.pop('_integrity', None)
    expected_tag = compute_integrity_tag(data)
    if not hmac.compare_digest(stored_tag or '', expected_tag):
        return None

    data['_integrity'] = stored_tag
    return data

def save_session(session_id, data):
    """Save session data to disk with integrity protection."""
    path = resolve_session_path(session_id)
    if path is None:
        return False

    data['_integrity'] = compute_integrity_tag(
        {k: v for k, v in data.items() if k != '_integrity'}
    )

    with open(path, 'w') as f:
        json.dump(data, f)

    return True

def validate_username(username):
    """Validate username format - allows unicode usernames."""
    if not username or len(username) > 64:
        return False
    # Allow alphanumeric, dots, hyphens, underscores, and unicode letters
    if not re.match(r'^[\w.\-]+$', username, re.UNICODE):
        return False
    return True

def get_user_role(username):
    """Look up user role from configuration."""
    admin_users = os.environ.get('ADMIN_USERS', 'admin').split(',')
    if username in admin_users:
        return 'admin'
    return 'user'

@app.route('/auth/login', methods=['POST'])
def login():
    """Authenticate user and create session."""
    data = request.get_json()
    if not data:
        abort(400)

    username = data.get('username', '')
    password = data.get('password', '')

    if not validate_username(username):
        abort(400, 'Invalid username format')

    # In production, verify against password database
    # For this service, we verify against env-configured credentials.
    # Stored credential is a salted PBKDF2 hash, not a raw SHA-256 digest.
    stored_credential = os.environ.get(f'USER_HASH_{username.upper()}', '')
    if not stored_credential:
        abort(401)

    if not verify_password(password, stored_credential):
        abort(401)

    session_id = generate_session_id(username)
    role = get_user_role(username)

    session_data = {
        'username': username,
        'role': role,
        'created_at': time.time(),
        'ip': request.remote_addr
    }

    if not save_session(session_id, session_data):
        abort(500)

    return jsonify({'session_id': session_id, 'role': role})

@app.route('/auth/session/<session_id>', methods=['GET'])
def get_session(session_id):
    """Retrieve session information."""
    session = load_session(session_id)
    if session is None:
        abort(401)

    return jsonify({
        'username': session['username'],
        'role': session['role'],
        'created_at': session['created_at']
    })

@app.route('/admin/users', methods=['GET'])
def list_users():
    """Admin endpoint to list active sessions."""
    session_id = request.headers.get('X-Session-Id', '')
    session = load_session(session_id)

    if session is None or session.get('role') != 'admin':
        abort(403)

    sessions = []
    for fname in os.listdir(SESSION_DIR):
        if fname.endswith('.json'):
            fpath = os.path.join(SESSION_DIR, fname)
            try:
                with open(fpath, 'r') as f:
                    sdata = json.load(f)
                if time.time() - sdata.get('created_at', 0) <= MAX_SESSION_AGE:
                    sessions.append({
                        'username': sdata.get('username'),
                        'role': sdata.get('role'),
                        'created_at': sdata.get('created_at')
                    })
            except (json.JSONDecodeError, IOError):
                continue

    return jsonify({'active_sessions': sessions})

@app.route('/admin/impersonate', methods=['POST'])
def impersonate():
    """Admin endpoint to create a session as another user."""
    session_id = request.headers.get('X-Session-Id', '')
    session = load_session(session_id)

    if session is None or session.get('role') != 'admin':
        abort(403)

    data = request.get_json()
    target_user = data.get('target_username', '')

    if not validate_username(target_user):
        abort(400)

    new_session_id = generate_session_id(target_user)
    new_session_data = {
        'username': target_user,
        'role': get_user_role(target_user),
        'created_at': time.time(),
        'ip': request.remote_addr,
        'impersonated_by': session['username']
    }

    if not save_session(new_session_id, new_session_data):
        abort(500)

    return jsonify({'session_id': new_session_id, 'target': target_user})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
